import{_ as a,c as i,o as l,ag as t}from"./chunks/framework.D6L8gzMI.js";const p=JSON.parse('{"title":"redis","description":"","frontmatter":{"title":"redis"},"headers":[],"relativePath":"review/4-3.md","filePath":"review/4-3.md","lastUpdated":1743652628000}'),r={name:"review/4-3.md"};function s(o,e,d,n,h,u){return l(),i("div",null,e[0]||(e[0]=[t('<h1 id="redis快的原因" tabindex="-1">Redis快的原因 <a class="header-anchor" href="#redis快的原因" aria-label="Permalink to &quot;Redis快的原因&quot;">​</a></h1><h2 id="纯内存操作" tabindex="-1">纯内存操作 <a class="header-anchor" href="#纯内存操作" aria-label="Permalink to &quot;纯内存操作&quot;">​</a></h2><p>Redis所有数据操作均在内存中完成，避免传统磁盘数据库的I/O瓶颈。内存操作速度可达纳秒级，相比磁盘访问(毫秒级)提升5个数量级，奠定性能基础‌ 。</p><h2 id="高性能数据结构" tabindex="-1">高性能数据结构 <a class="header-anchor" href="#高性能数据结构" aria-label="Permalink to &quot;高性能数据结构&quot;">​</a></h2><p>内置优化数据结构：字符串、跳跃表、压缩列表、哈希表等针对不同场景设计（如压缩列表减少短数据内存占用，跳跃表实现快速范围查询）</p><p>Redis内置的8种数据结构经过精细优化：</p><ul><li>哈希表采用 双表 渐进式rehash，平均时间复杂度保持O(1)</li><li>压缩列表（ziplist）和整数集合（intset）将小数据存储密度提升3-5倍</li><li>跳跃表（skiplist）在有序集合操作中，提供平均O(log n)的查询性能，<strong>空间  开销</strong>  比平衡树低40%</li></ul><h2 id="单线程-无锁架构" tabindex="-1">单线程 无锁架构 <a class="header-anchor" href="#单线程-无锁架构" aria-label="Permalink to &quot;单线程 无锁架构&quot;">​</a></h2><p>Redis采用单线程模型处理所有客户端请求，消除了多线程环境下的上下文切换开销（每次切换约需微秒级）和锁竞争。</p><ul><li>单线程模型避免多线程上下文切换（每次切换约1μs）和锁竞争开销</li><li>原子性操作天然避免并发安全问题，指令执行无阻塞</li><li>CPU缓存命中率更高（L1缓存访问仅0.5ns）</li></ul><h2 id="事件驱动-io多路复用" tabindex="-1">事件驱动 + IO多路复用 <a class="header-anchor" href="#事件驱动-io多路复用" aria-label="Permalink to &quot;事件驱动 + IO多路复用&quot;">​</a></h2><p>通过epoll/kqueue等IO多路复用技术，Redis实现了单线程同时处理数万个客户端连接。这种机制将网络事件（读、写、连接）转化为非阻塞事件，CPU利用率高达95%。</p><ul><li>Reactor模式实现单线程处理20万+连接</li><li>epoll/kqueue系统调用实现μs级事件触发，对比传统阻塞IO模型吞吐量提升100倍</li><li>网络包解析与命令执行流水线化，事件分派延迟&lt;1ms‌</li></ul><h2 id="异步日志" tabindex="-1">异步日志 <a class="header-anchor" href="#异步日志" aria-label="Permalink to &quot;异步日志&quot;">​</a></h2><p>Redis的RDB和AOF进行异步持久化，并且优化了策略。提供了灵活的性能-可靠性权衡：</p><ul><li>持久化采用RDB快照（fork子进程写入）与AOF日志（后台线程fsync）分离</li><li>日志写入延迟从同步模式的10ms级降低至异步模式100μs级</li><li>写操作缓冲区实现批量刷盘，吞吐量提升5-10倍‌</li><li>RDB每秒级快照，恢复速度达100MB/s</li><li>AOF追加写入支持fsync可配置，每秒持久化模式下性能损耗&lt;5% , 主从同步带宽占用&lt;10%，实现了高性能与可靠性的完美平衡。</li></ul>',16)]))}const _=a(r,[["render",s]]);export{p as __pageData,_ as default};
